/**
 * Curated catalog of well-known, secure integrations that UNIK can connect to.
 *
 * Each entry includes:
 * - Brand icon (lucide name + brand color)
 * - What it does (short + long description)
 * - Capabilities (what the user can do once connected)
 * - Connection steps (quick, step-by-step)
 * - Security info (auth type, encryption, scopes)
 * - Docs URL
 * - Category for grouping
 *
 * This is a static catalog — it does NOT create connections.
 * Selecting an entry pre-fills the extension creation form.
 */

export type CatalogKind = 'mcp' | 'api' | 'plugin' | 'skill';
export type CatalogAuthType = 'oauth' | 'api_key' | 'bearer' | 'none';
export type CatalogCategory =
  | 'Desarrollo'
  | 'Comunicaciones'
  | 'Productividad'
  | 'Pagos'
  | 'IA'
  | 'CRM'
  | 'Comercio'
